 void settings(){title("הגדרות","התאימי את הלן לסגנון העבודה שלך.");long modelBytes=ai==null?0:ai.modelSizeBytes();String modelState=aiReady?ai.backendName():(ai!=null&&ai.hasModel()?"המודל שמור · טעינה נדרשת":"טרם הורד");infoCard("מודל בינה מלאכותית","Gemma 4 E2B · כ־2.58GB · "+modelState+"\nקובץ מקומי: "+(modelBytes>0?(modelBytes/(1024*1024))+"MB":"לא קיים")+"\nהורדה חד־פעמית; לאחריה ניתן לעבוד ללא רשת.");if(!aiReady)button("↻  נסי שוב להוריד או להפעיל את המודל",()->retryAi());if(ai!=null&&ai.hasModel())button("פינוי מקום · מחיקת קובץ מודל Gemma 4",()->confirmDeleteModel());button("ניקוי היסטוריית שיחות",()->clearChatHistory());button("מצב תצוגה: "+(prefs.getBoolean("light_mode",false)?"בהיר":"כהה"),()->toggleTheme());body.addView(text("גודל טקסט",13,muted,true));SeekBar size=new SeekBar(this);size.setMax(50);size.setProgress(Math.max(0,Math.min(50,Math.round((textScale-.8f)*100))));body.addView(size);size.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar b,int p,boolean u){if(u){textScale=.8f+p/100f;prefs.edit().putFloat("text_scale",textScale).apply();}}public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){renderTab();}});body.addView(text("מהירות הקראה",13,muted,true));SeekBar speed=new SeekBar(this);speed.setMax(15);speed.setProgress(Math.max(0,Math.min(15,Math.round((prefs.getFloat("speech_rate",1f)-.6f)*10))));body.addView(speed);speed.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar b,int p,boolean u){if(u){float rate=.6f+p/10f;prefs.edit().putFloat("speech_rate",rate).apply();if(tts!=null)tts.setSpeechRate(rate);}}public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}});button("אודות HELEN AI",()->showAbout());button("שירות נגישות · לחיצה, הקלדה וגלילה",()->startActivity(new Intent(Settings.ACTION_ACCESSIBILITY_SETTINGS)));button("הרשאות אפליקציה",()->startActivity(new Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS,Uri.parse("package:"+getPackageName()))));button("הגדרות בהירות מסך",()->startActivity(new Intent(Settings.ACTION_DISPLAY_SETTINGS)));button("הגדרות Wi-Fi ו-Bluetooth",()->{if(Build.VERSION.SDK_INT>=29)startActivity(new Intent(Settings.Panel.ACTION_INTERNET_CONNECTIVITY));else startActivity(new Intent(Settings.ACTION_WIFI_SETTINGS));});button("גיבוי נתונים לקובץ",()->exportBackup());button("שחזור מגיבוי",()->importBackup());}
 void showAbout(){LinearLayout panelView=new LinearLayout(this);panelView.setOrientation(1);panelView.setGravity(Gravity.CENTER_HORIZONTAL);panelView.setPadding(dp(22),dp(18),dp(22),dp(18));TextView avatar=text("🧑🏻‍💻",58,white,true);avatar.setGravity(Gravity.CENTER);avatar.setBackground(shape(0xff263D31,64));LinearLayout.LayoutParams avatarP=new LinearLayout.LayoutParams(dp(112),dp(112));avatarP.bottomMargin=dp(14);panelView.addView(avatar,avatarP);TextView name=text("HELEN AI",22,white,true);panelView.addView(name);TextView version=text("גרסה 4.1 · Gemma 4 E2B · LiteRT-LM",12,muted,false);version.setPadding(0,dp(5),0,dp(14));panelView.addView(version);TextView aboutText=text("העוזרת האישית שלך, עם בינה מלאכותית מקומית, שיחה בעברית והשלמת משפטים.\n\nפותחה באהבה על ידי ספרדי גאה.\n\nהפרטיות חשובה לנו: השיחה עם המודל מתבצעת במכשיר לאחר הורדת המודל.",14,white,false);aboutText.setGravity(Gravity.CENTER);panelView.addView(aboutText);new AlertDialog.Builder(this).setView(panelView).setPositiveButton("סגירה",null).show();}
 void applyThemePalette(boolean light){if(light){bg=0xffF2F5F1;panel=0xffE4EBE4;card=0xffFFFFFF;green=0xff426B27;muted=0xff647168;white=0xff18231B;}else{bg=0xff0B100D;panel=0xff151E18;card=0xff1C2921;green=0xffC7F36B;muted=0xff91A096;white=0xffF3F7F1;}getWindow().setStatusBarColor(bg);getWindow().setNavigationBarColor(bg);}
